def batch_key(value):
    """Normalize a batch key into a (first, second, third) tuple.

    The input must be a string with exactly three nonempty components
    separated by colons. Each component is stripped of surrounding
    whitespace; the first and second are case-folded, the third is kept
    case-sensitive. Whitespace inside a stripped component is invalid.
    """
    if not isinstance(value, str):
        raise ValueError("batch key must be a string")

    parts = value.split(":")
    if len(parts) != 3:
        raise ValueError("batch key must have exactly three components")

    stripped = []
    for part in parts:
        component = part.strip()
        if not component:
            raise ValueError("batch key components must be nonempty")
        if any(ch.isspace() for ch in component):
            raise ValueError("batch key components must not contain whitespace")
        stripped.append(component)

    return (stripped[0].casefold(), stripped[1].casefold(), stripped[2])

