def _require_int(value, name):
    if type(value) is not int:
        raise ValueError(f"{name} must be a plain int")


def clip_spans(spans, low, high):
    """Intersect half-open intervals with the half-open range [low, high).

    Returns a new list of tuples in input order, dropping empty intersections.
    """
    _require_int(low, "low")
    _require_int(high, "high")
    if low > high:
        raise ValueError("low must be <= high")

    result = []
    for span in spans:
        if not isinstance(span, (tuple, list)) or len(span) != 2:
            raise ValueError("each span must be a (start, end) pair")
        start, end = span
        _require_int(start, "start")
        _require_int(end, "end")
        if start > end:
            raise ValueError("start must be <= end")

        clipped_start = max(start, low)
        clipped_end = min(end, high)
        if clipped_start < clipped_end:
            result.append((clipped_start, clipped_end))

    return result

