def _is_plain_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def clip_spans(spans, low, high):
    """Intersect half-open intervals with [low, high).

    Validates all bounds and every interval before clipping. Returns a new
    list of tuples in input order, dropping empty intersections.
    """
    if not _is_plain_int(low) or not _is_plain_int(high):
        raise ValueError("low and high must be plain ints")
    if low > high:
        raise ValueError("low must be <= high")

    intervals = list(spans)
    for span in intervals:
        if not isinstance(span, tuple) or len(span) != 2:
            raise ValueError("each span must be a (start, end) tuple")
        start, end = span
        if not _is_plain_int(start) or not _is_plain_int(end):
            raise ValueError("span bounds must be plain ints")
        if start > end:
            raise ValueError("span start must be <= end")

    result = []
    for start, end in intervals:
        clipped_start = max(start, low)
        clipped_end = min(end, high)
        if clipped_start < clipped_end:
            result.append((clipped_start, clipped_end))
    return result

