def daily_counters(rows):
    """Aggregate (day, name, delta) tuples into per-day, per-name sums.

    Returns a new dict keyed by day; each value is a dict mapping name to the
    summed delta. Zero sums are retained, as are negative sums. Raises
    ValueError for malformed rows or invalid fields.
    """
    result = {}
    for row in rows:
        try:
            day, name, delta = row
        except (TypeError, ValueError):
            raise ValueError("each row must be a (day, name, delta) triple")
        if not isinstance(day, str) or not day:
            raise ValueError("day must be a nonempty string")
        if not isinstance(name, str) or not name:
            raise ValueError("name must be a nonempty string")
        if isinstance(delta, bool) or not isinstance(delta, int):
            raise ValueError("delta must be a plain integer")
        bucket = result.setdefault(day, {})
        bucket[name] = bucket.get(name, 0) + delta
    return result

